<#
.SYNOPSIS
Collects the target forest's Active Directory schema class GUID map for Directory Control evaluation.
.NOTES
Version: 1.0.0
#>
[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$OutputDirectory,[string]$Server,[PSCredential]$Credential,[switch]$NoColor)
Set-StrictMode -Version 2.0;$ErrorActionPreference='Stop';$ModuleId='Invoke-MSADPTDirectoryControlSchemaClassMap';$ModuleVersion='1.0.0';function Show([string]$s,[string]$m,[ConsoleColor]$c=[ConsoleColor]::Gray){$t='[{0,-12}] {1}'-f$s,$m;if($NoColor){Write-Host $t}else{Write-Host $t -ForegroundColor$c}};if($null-eq(Get-Module -ListAvailable ActiveDirectory|Select-Object -First 1)){throw 'ActiveDirectoryModuleUnavailable'};Import-Module ActiveDirectory -ErrorAction Stop;$p=@{ErrorAction='Stop'};if($Server){$p.Server=$Server};if($Credential){$p.Credential=$Credential};$Target=if($Server){$Server}else{'current forest'};Show START "$ModuleId v$ModuleVersion" Cyan;Show NETWORK "Target=$Target; protocol=ADWS/LDAP; operation=read RootDSE and classSchema objects; changes=None." Magenta;$Root=Get-ADRootDSE @p;$q=$p.Clone();$q.SearchBase=[string]$Root.SchemaNamingContext;$q.LDAPFilter='(objectClass=classSchema)';$q.Properties=@('lDAPDisplayName','schemaIDGUID','governsID','subClassOf');$Rows=New-Object 'Collections.Generic.List[object]';foreach($c in @(Get-ADObject @q)){try{$guid=New-Object Guid (,$c.schemaIDGUID);$Rows.Add([pscustomobject]@{LdapDisplayName=[string]$c.lDAPDisplayName;SchemaIdGuid=$guid.ToString().ToLowerInvariant();GovernsId=[string]$c.governsID;SubClassOf=[string]$c.subClassOf;DistinguishedName=[string]$c.DistinguishedName})}catch{}};New-Item -ItemType Directory -Path $OutputDirectory -Force|Out-Null;$csv=Join-Path $OutputDirectory 'directory-control-schema-class-map.csv';$json=Join-Path $OutputDirectory 'directory-control-schema-class-map.json';$Rows.ToArray()|Sort-Object LdapDisplayName|Export-Csv $csv -NoTypeInformation -Encoding UTF8;$Rows.ToArray()|Sort-Object LdapDisplayName|ConvertTo-Json -Depth 8|Set-Content $json -Encoding UTF8;$Summary=[pscustomobject]@{SchemaVersion='1.0';ModuleId=$ModuleId;ModuleVersion=$ModuleVersion;Status='Completed';Disposition=if($Rows.Count){'Collected'}else{'Inconclusive'};GeneratedUtc=(Get-Date).ToUniversalTime().ToString('o');SchemaNamingContext=[string]$Root.SchemaNamingContext;ClassCount=$Rows.Count;Safety=[pscustomobject]@{NetworkActivity='ReadOnlyADQueries';DirectoryChanges='None';RemoteChanges='None'}};$Summary|ConvertTo-Json -Depth 8|Set-Content (Join-Path $OutputDirectory 'directory-control-schema-class-summary.json') -Encoding UTF8;$files=@(Get-ChildItem $OutputDirectory -File|Where-Object Name -ne'evidence-manifest.json'|ForEach-Object{[pscustomobject]@{Name=$_.Name;Size=$_.Length;SHA256=(Get-FileHash $_.FullName -Algorithm SHA256).Hash}});[pscustomobject]@{SchemaVersion='1.0';Status='Completed';ModuleId=$ModuleId;ModuleVersion=$ModuleVersion;FileCount=$files.Count;Files=$files}|ConvertTo-Json -Depth 8|Set-Content (Join-Path $OutputDirectory 'evidence-manifest.json') -Encoding UTF8;Show DONE "Schema classes=$($Rows.Count)." Green;[pscustomobject]@{Status='Passed';ModuleId=$ModuleId;ModuleVersion=$ModuleVersion;ClassCount=$Rows.Count;ClassMapPath=$csv;NetworkActivity='ReadOnlyADQueries';RemoteChanges='None'}
